        B(px - 1, py - 1, db + 1, 2, 2, 3, P.copper);
      }
      for (let r = -3; r <= 3; r += 3) {
        const py = yp + r;
        const db = dzRow(xp, Math.floor((py - (CY - R0)) / 2) * 2 + (CY - R0));
        const st = (idx % 3 === 2) ? P.ice : P.lamp;
        B(xp - 3, py, db + 1, 7, 3, 1, st);
      }
      // 窗下暖铜铭牌
      B(xp - 4, yp - 9, dz + 1, 9, 2, 1, P.copperL);
    });

    // 舱门
    const xh = 40, yh = CY - 2;
