    t = Math.min(1, Math.max(0, t));
    for (let i = 0; i < CP.length - 1; i++) {
      const a = CP[i], b = CP[i + 1];
      if (t <= b[0]) {
        const u = (b[0] - a[0]) === 0 ? 0 : (t - a[0]) / (b[0] - a[0]);
