      B(x, 2, z, 4, h, 4, P.copperL);
      for (let i = 0; i < 3; i++) {
        B(x - w / 2 + i, 3 + i * Math.round(h / 3), z, w - i * 2, Math.round(h / 3) + 2, 3, st);
